<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useI18n } from 'vue-i18n'
import { Eye, EyeOff, ExternalLink, RefreshCw } from 'lucide-vue-next'
import appIcon from '@/assets/icon-settings.png'
import { isTauri } from '@/hooks/useTauri'
import { useSettingsStore, type ThemeId } from '@/stores/settingsStore'
import { useZustandSelector } from '@/composables/useZustandSelector'
import { CHAT_PROTOCOL_CAPABILITIES, SUPPORTED_CHAT_PROTOCOLS, getChatProtocolCapabilities, initAiClient, initEmbeddingClient, isLocalApi, testAiConnection, validateAiStatus } from '@/services/ai/aiClient'
import { AI_CHAT_PRESETS, AI_EMBEDDING_PRESETS, type ChatProtocol, type EmbeddingProtocol, type ValidateResult } from '@/services/ai/types'
import { testWebSearchConnection, type WebSearchTestResult, type SearchProvider } from '@/services/webSearch'
import { externalFetch } from '@/services/externalHttp'
import { DEFAULT_REQUEST_TIMEOUT_MS } from '@/services/requestTimeout'
import { SHORTCUTS, findShortcutConflicts } from '@/services/shortcuts'
import { clearAllChatSessions, clearMemoriesByStatus } from '@/services/database/persistence'
import { exportDataBackup, importDataBackup } from '@/services/dataBackup'
import { useChatStore } from '@/stores/chatStore'
import { useAppStore } from '@/stores/appStore'
import { getCurrentAppVersion, getCurrentVersionRelease, GITHUB_REPOSITORY_URL, openReleaseInSystemBrowser } from '@/services/updateService'
import { runManualUpdateCheck, type ManualUpdateCheckFeedback } from '@/services/updateNotifications'
import { useUpdateStore } from '@/stores/updateStore'
import { requestProductTour } from '@/features/productTour/productTourEvents'
import { toast } from '@/services/toast'
import VueAiShortcutSettings from './VueAiShortcutSettings.vue'
import VueAiPresetManager from './VueAiPresetManager.vue'
import VueAuthorizedApiOrigins from './VueAuthorizedApiOrigins.vue'
import VueKnowledgeBaseManager from './VueKnowledgeBaseManager.vue'
import VueKnowledgeStats from './VueKnowledgeStats.vue'
import VueLegacyMigrationEntry from './VueLegacyMigrationEntry.vue'
import VueThemePicker from './VueThemePicker.vue'
import VueMemorySettings from './VueMemorySettings.vue'
import VueUsageActivity from './VueUsageActivity.vue'

const { t } = useI18n()
const props = withDefaults(defineProps<{ initialSection?: string | null }>(), { initialSection: null })
const active = ref('ai'), knowledgeManagerOpen = ref(false), showChatKey = ref(false), showEmbeddingKey = ref(false), showSearchKey = ref(false), showChatPresetSave = ref(false), showEmbeddingPresetSave = ref(false), chatPresetName = ref(''), embeddingPresetName = ref('')
const chatTesting = ref(false), embTesting = ref(false), webTesting = ref(false), chatResult = ref<ValidateResult | null>(null), embResult = ref<ValidateResult | null>(null), webResult = ref<WebSearchTestResult | null>(null), currentVersion = ref('—'), busy = ref(false), checkingUpdate = ref(false), loadingNotes = ref(false), updateFeedback = ref<ManualUpdateCheckFeedback | null>(null)
const ai = useZustandSelector(useSettingsStore, (state) => state.ai)
const editor = useZustandSelector(useSettingsStore, (state) => state.editor)
const appearance = useZustandSelector(useSettingsStore, (state) => state.appearance)
const webSearch = useZustandSelector(useSettingsStore, (state) => state.webSearch)
const knowledge = useZustandSelector(useSettingsStore, (state) => state.knowledge)
const chatPresets = useZustandSelector(useSettingsStore, (state) => state.customChatPresets)
const embeddingPresets = useZustandSelector(useSettingsStore, (state) => state.customEmbeddingPresets)
const tabs = [{ key: 'ai', label: t('settings.tabAi') }, { key: 'editor', label: t('settings.tabEditor') }, { key: 'memory', label: t('settings.tabMemory') }, { key: 'ai-shortcuts', label: t('settings.tabAiShortcuts') }, { key: 'shortcuts', label: t('settings.tabShortcuts') }, { key: 'general', label: t('settings.tabGeneral') }]
const chatProtocolOptions = SUPPORTED_CHAT_PROTOCOLS.map((key) => ({ key, label: CHAT_PROTOCOL_CAPABILITIES[key].label }))
const chatPresetOptions = computed(() => [...chatPresets.value.filter((item) => item.protocol === ai.value.protocol).map((item) => ({ key: item.id, label: item.label })), ...AI_CHAT_PRESETS.filter((item) => item.key === 'custom' || item.protocol === ai.value.protocol).map((item) => ({ key: item.key, label: item.label }))])
const embeddingPresetOptions = computed(() => [...embeddingPresets.value.filter((item) => item.protocol === ai.value.embedding.protocol).map((item) => ({ key: item.id, label: item.label })), ...AI_EMBEDDING_PRESETS.filter((item) => item.key === 'custom' || item.protocol === ai.value.embedding.protocol).map((item) => ({ key: item.key, label: item.label }))])
const chatPreset = computed(() => chatPresets.value.find((item) => item.protocol === ai.value.protocol && item.baseUrl === ai.value.baseUrl && item.chatModel === ai.value.chatModel)?.id ?? AI_CHAT_PRESETS.find((item) => item.key !== 'custom' && item.protocol === ai.value.protocol && item.baseUrl === ai.value.baseUrl && item.chatModel === ai.value.chatModel)?.key ?? 'custom')
const embeddingPreset = computed(() => embeddingPresets.value.find((item) => item.protocol === ai.value.embedding.protocol && item.baseUrl === ai.value.embedding.baseUrl && item.embeddingModel === ai.value.embedding.embeddingModel)?.id ?? AI_EMBEDDING_PRESETS.find((item) => item.key !== 'custom' && item.protocol === ai.value.embedding.protocol && item.baseUrl === ai.value.embedding.baseUrl && item.embeddingModel === ai.value.embedding.embeddingModel)?.key ?? 'custom')
const modeDescription = computed(() => ({ memory: t('settings.modeDescriptionMemory'), balanced: t('settings.modeDescriptionBalanced'), speed: t('settings.modeDescriptionSpeed') })[editor.value.modePerformancePolicy])
function updateAi(field: string, value: unknown): void { useSettingsStore.getState().updateAiConfig({ [field]: value }) }
function updateEmbedding(field: string, value: unknown): void { useSettingsStore.getState().updateEmbeddingConfig({ [field]: value }) }
function updateSearch(field: string, value: unknown): void { useSettingsStore.getState().updateWebSearchConfig({ [field]: value }) }
function updateEditor(field: string, value: unknown): void { useSettingsStore.getState().updateEditorSettings({ [field]: value }) }
function updateAppearance(field: string, value: unknown): void { useSettingsStore.getState().updateAppearanceSettings({ [field]: value }) }
function selectChatPreset(key: string): void { const system = AI_CHAT_PRESETS.find((item) => item.key === key), custom = chatPresets.value.find((item) => item.id === key); const preset = system?.key !== 'custom' ? system : custom; if (preset) useSettingsStore.getState().updateAiConfig({ protocol: preset.protocol as ChatProtocol, provider: preset.provider, baseUrl: preset.baseUrl, chatModel: preset.chatModel ?? '' }) }
function selectEmbeddingPreset(key: string): void { const system = AI_EMBEDDING_PRESETS.find((item) => item.key === key), custom = embeddingPresets.value.find((item) => item.id === key); const preset = system?.key !== 'custom' ? system : custom; if (preset) useSettingsStore.getState().updateEmbeddingConfig({ protocol: preset.protocol as EmbeddingProtocol, provider: preset.provider, baseUrl: preset.baseUrl, embeddingModel: preset.embeddingModel ?? '' }) }
function saveChatPreset(): void { const label = chatPresetName.value.trim(); if (!label) return; useSettingsStore.getState().addCustomChatPreset({ id: `custom-chat-${Date.now()}`, label, protocol: ai.value.protocol, provider: ai.value.provider, baseUrl: ai.value.baseUrl, chatModel: ai.value.chatModel }); chatPresetName.value = ''; showChatPresetSave.value = false; toast.success(t('settings.presetSaved', { label })) }
function saveEmbeddingPreset(): void { const label = embeddingPresetName.value.trim(); if (!label) return; useSettingsStore.getState().addCustomEmbeddingPreset({ id: `custom-emb-${Date.now()}`, label, protocol: ai.value.embedding.protocol, provider: ai.value.embedding.provider, baseUrl: ai.value.embedding.baseUrl, embeddingModel: ai.value.embedding.embeddingModel }); embeddingPresetName.value = ''; showEmbeddingPresetSave.value = false; toast.success(t('settings.embeddingPresetSaved', { label })) }
async function testChat(): Promise<void> { chatTesting.value = true; chatResult.value = null; try { const capability = getChatProtocolCapabilities(ai.value.protocol); chatResult.value = capability.implemented ? await testAiConnection(ai.value) : { ok: false, error: 'config', message: capability.unsupportedReason } } catch (error) { chatResult.value = { ok: false, error: 'unknown', message: error instanceof Error ? error.message : String(error) } } finally { chatTesting.value = false } }
async function testEmbedding(): Promise<void> { embTesting.value = true; embResult.value = null; try { const config = ai.value.embedding; if (!config.baseUrl) { embResult.value = { ok: false, error: 'config', message: t('settings.embeddingBaseUrlMissing') }; return }; const response = await externalFetch(`${config.baseUrl.replace(/\/+$/, '')}/embeddings`, { method: 'POST', headers: { 'Content-Type': 'application/json', ...(config.apiKey ? { Authorization: `Bearer ${config.apiKey}` } : {}) }, body: JSON.stringify({ model: config.embeddingModel, input: 'test' }) }); embResult.value = response.ok ? { ok: true } : { ok: false, error: 'http', message: t('settings.embeddingConnectionFailed', { status: response.status }) } } catch (error) { embResult.value = { ok: false, error: 'unknown', message: error instanceof Error ? error.message : String(error) } } finally { embTesting.value = false } }
async function testWeb(): Promise<void> { webTesting.value = true; webResult.value = null; try { webResult.value = await testWebSearchConnection(webSearch.value) } catch (error) { webResult.value = { ok: false, message: error instanceof Error ? error.message : String(error) } } finally { webTesting.value = false } }
function restoreDefaults(): void { const state = useSettingsStore.getState(); state.updateAiConfig({ protocol: 'openai-chat', provider: 'custom', baseUrl: '', chatModel: '', streamEnabled: true, webSearchEnabled: false, customPreferencePrompt: '', timeout: 60_000, maxContextLength: 8192, temperature: .7, topP: 1 }); state.updateEmbeddingConfig({ protocol: 'openai-embedding', provider: 'custom', baseUrl: '', embeddingModel: '', timeout: DEFAULT_REQUEST_TIMEOUT_MS }); state.updateEditorSettings({ fontSize: 14, lineHeight: 1.65, tabSize: 2, wordWrap: true, lineNumbers: true, autoSave: true, autoSaveDelay: 1000, syncScroll: true, autoSendAiShortcut: true, inlinePreviewEdit: true, modePerformancePolicy: 'balanced', defaultOpenMode: 'preview' }); state.updateAppearanceSettings({ customCursorEnabled: true, aiMascotAvatarEnabled: false, themeId: 'dark' }); state.updateWebSearchConfig({ provider: 'duckduckgo', apiKey: '', maxResults: 5, customUrl: '', timeout: DEFAULT_REQUEST_TIMEOUT_MS }); state.resetAiShortcutActions(); toast.success(t('settings.defaultsRestored')) }
async function exportBackup(): Promise<void> { busy.value = true; try { toast.success(t('settings.backupExported', { path: await exportDataBackup() })) } catch (error) { if ((error as Error).message !== t('settings.exportCancelled')) toast.error(error instanceof Error ? error.message : t('settings.exportFailed')) } finally { busy.value = false } }
async function importBackup(): Promise<void> { busy.value = true; try { const result = await importDataBackup(); toast.success(t('settings.backupImported', { sessions: result.sessions, messages: result.messages, memories: result.memories, artifacts: result.artifacts })) } catch (error) { if ((error as Error).message !== t('settings.importCancelled')) toast.error(error instanceof Error ? error.message : t('settings.importFailed')) } finally { busy.value = false } }
async function clearSessions(): Promise<void> { if (!window.confirm(t('settings.clearSessionsConfirm'))) return; busy.value = true; try { await clearAllChatSessions(); useChatStore.getState().resetHistoryState(); toast.success(t('settings.sessionsCleared')) } catch (error) { toast.error(error instanceof Error ? error.message : t('settings.clearSessionsFailed')) } finally { busy.value = false } }
async function clearCandidates(): Promise<void> { if (!window.confirm(t('settings.clearCandidatesConfirm'))) return; busy.value = true; try { await clearMemoriesByStatus(['candidate']); toast.success(t('settings.candidatesCleared')) } catch (error) { toast.error(error instanceof Error ? error.message : t('settings.clearCandidatesFailed')) } finally { busy.value = false } }
async function checkUpdate(): Promise<void> { checkingUpdate.value = true; updateFeedback.value = null; try { updateFeedback.value = await runManualUpdateCheck() } finally { checkingUpdate.value = false } }
async function showVersion(): Promise<void> { loadingNotes.value = true; try { useUpdateStore.getState().showDetails(await getCurrentVersionRelease()) } catch { toast.error(t('settings.versionInfoFailed')) } finally { loadingNotes.value = false } }
function openGuide(): void { void (isTauri() ? import('@tauri-apps/plugin-shell').then(({ open }) => open('https://github.com/we-used-to-be/Guanmo-open/blob/main/docs/AI_ROUTING_GUIDE.md')) : Promise.resolve(window.open('https://github.com/we-used-to-be/Guanmo-open/blob/main/docs/AI_ROUTING_GUIDE.md', '_blank', 'noopener,noreferrer'))) }
watch(() => props.initialSection, (value) => { if (value && tabs.some((item) => item.key === value)) active.value = value }, { immediate: true })
watch([ai, webSearch], () => { const timer = window.setTimeout(() => { try { if ((ai.value.apiKey || isLocalApi(ai.value.baseUrl)) && ai.value.baseUrl && ai.value.chatModel) initAiClient(ai.value); if ((ai.value.embedding.apiKey || isLocalApi(ai.value.embedding.baseUrl)) && ai.value.embedding.baseUrl && ai.value.embedding.embeddingModel) initEmbeddingClient(ai.value.embedding); void validateAiStatus().then((status) => useAppStore.getState().setAiStatus(status)) } catch {} }, 1_000); return () => window.clearTimeout(timer) }, { deep: true })
onMounted(() => { if (!isTauri()) { currentVersion.value = t('settings.webVersion'); return }; void getCurrentAppVersion().then((value) => currentVersion.value = `v${value}`).catch(() => currentVersion.value = t('settings.unknownVersion')) })
onBeforeUnmount(() => {})
</script>

<template>
  <section class="gm-vue-settings"><div class="gm-vue-settings__body"><nav role="tablist" autofocus><button v-for="tab in tabs" :key="tab.key" type="button" :data-active="active === tab.key" role="tab" :aria-selected="active === tab.key" @click="active = tab.key">{{ tab.label }}</button></nav><main>
    <section v-if="active === 'ai'" class="gm-vue-settings-pane"><p v-if="!isTauri()" class="gm-vue-settings-notice">{{ t('settings.browserAiNotice') }}</p><div class="gm-vue-settings-row"><span><b>{{ t('settings.aiGuideTitle') }}</b><small>{{ t('settings.aiGuideDescription') }}</small></span><button type="button" @click="openGuide">{{ t('settings.viewGuide') }}<ExternalLink :size="13" /></button></div><h3>{{ t('settings.chatApiSection') }}</h3><div class="gm-vue-settings-row"><span><b>{{ t('settings.protocolLabel') }}</b><small>{{ t('settings.protocolDescription') }}</small></span><select :value="ai.protocol" @change="updateAi('protocol', ($event.target as HTMLSelectElement).value as ChatProtocol); updateAi('provider', 'custom')"><option v-for="option in chatProtocolOptions" :key="option.key" :value="option.key">{{ option.label }}</option></select></div><div class="gm-vue-settings-row"><span><b>{{ t('settings.presetLabel') }}</b><small>{{ t('settings.presetDescription') }}</small></span><select :value="chatPreset" @change="selectChatPreset(($event.target as HTMLSelectElement).value)"><option v-for="option in chatPresetOptions" :key="option.key" :value="option.key">{{ option.label }}</option></select></div><label class="gm-vue-settings-row"><span><b>{{ t('settings.baseUrlLabel') }}</b><small>{{ t('settings.baseUrlDescription') }}</small></span><input :value="ai.baseUrl" placeholder="https://api.openai.com/v1" @input="updateAi('baseUrl', ($event.target as HTMLInputElement).value)" /></label><label v-if="!isLocalApi(ai.baseUrl)" class="gm-vue-settings-row"><span><b>{{ t('settings.apiKeyLabel') }}</b><small>{{ t('settings.apiKeyDescription') }}</small></span><div class="gm-vue-settings-input-action"><input :type="showChatKey ? 'text' : 'password'" :value="ai.apiKey" placeholder="sk-..." :disabled="!isTauri()" @input="updateAi('apiKey', ($event.target as HTMLInputElement).value)" /><button type="button" :title="showChatKey ? t('settings.hideKey') : t('settings.showKey')" @click="showChatKey = !showChatKey"><EyeOff v-if="showChatKey" :size="14" /><Eye v-else :size="14" /></button></div></label><label class="gm-vue-settings-row"><span><b>{{ t('settings.chatModelLabel') }}</b><small>{{ t('settings.chatModelDescription') }}</small></span><input :value="ai.chatModel" placeholder="gpt-4o-mini" @input="updateAi('chatModel', ($event.target as HTMLInputElement).value)" /></label><div class="gm-vue-settings-actions"><button type="button" :disabled="chatTesting || !getChatProtocolCapabilities(ai.protocol).implemented" @click="testChat">{{ chatTesting ? t('settings.connecting') : t('settings.testConnection') }}</button><button v-if="chatPreset !== 'custom' && chatPresets.some((item) => item.id === chatPreset)" type="button" class="gm-vue-settings-danger" @click="useSettingsStore.getState().removeCustomChatPreset(chatPreset)">{{ t('settings.deletePreset') }}</button></div><p v-if="chatResult" :class="chatResult.ok ? 'gm-vue-settings-success' : 'gm-vue-settings-error'">{{ chatResult.ok ? t('settings.connectionSuccess') : chatResult.message || t('settings.connectionFailed') }}</p><div class="gm-vue-settings-row"><span><b>{{ t('settings.timeoutLabel') }}</b><small>{{ t('settings.timeoutDescription') }}</small></span><input type="range" min="5" max="300" step="5" :value="ai.timeout / 1000" @input="updateAi('timeout', Number(($event.target as HTMLInputElement).value) * 1000)" /></div><h3>{{ t('settings.embeddingSection') }}</h3><div class="gm-vue-settings-row"><span><b>{{ t('settings.presetLabel') }}</b><small>{{ t('settings.embeddingPresetDescription') }}</small></span><select :value="embeddingPreset" @change="selectEmbeddingPreset(($event.target as HTMLSelectElement).value)"><option v-for="option in embeddingPresetOptions" :key="option.key" :value="option.key">{{ option.label }}</option></select></div><label class="gm-vue-settings-row"><span><b>{{ t('settings.baseUrlLabel') }}</b><small>{{ t('settings.embeddingBaseUrlDescription') }}</small></span><input :value="ai.embedding.baseUrl" placeholder="https://api.openai.com/v1" @input="updateEmbedding('baseUrl', ($event.target as HTMLInputElement).value)" /></label><label v-if="!isLocalApi(ai.embedding.baseUrl)" class="gm-vue-settings-row"><span><b>{{ t('settings.apiKeyLabel') }}</b><small>{{ t('settings.embeddingKeyDescription') }}</small></span><div class="gm-vue-settings-input-action"><input :type="showEmbeddingKey ? 'text' : 'password'" :value="ai.embedding.apiKey" placeholder="sk-..." :disabled="!isTauri()" @input="updateEmbedding('apiKey', ($event.target as HTMLInputElement).value)" /><button type="button" @click="showEmbeddingKey = !showEmbeddingKey"><EyeOff v-if="showEmbeddingKey" :size="14" /><Eye v-else :size="14" /></button></div></label><label class="gm-vue-settings-row"><span><b>{{ t('settings.embeddingModelLabel') }}</b><small>{{ t('settings.embeddingModelDescription') }}</small></span><input :value="ai.embedding.embeddingModel" placeholder="text-embedding-3-small" @input="updateEmbedding('embeddingModel', ($event.target as HTMLInputElement).value)" /></label><div class="gm-vue-settings-actions"><button type="button" :disabled="embTesting" @click="testEmbedding">{{ embTesting ? t('settings.connecting') : t('settings.testConnection') }}</button></div><p v-if="embResult" :class="embResult.ok ? 'gm-vue-settings-success' : 'gm-vue-settings-error'">{{ embResult.ok ? t('settings.connectionSuccess') : embResult.message || t('settings.connectionFailed') }}</p><h3>{{ t('settings.chatParamsSection') }}</h3><div class="gm-vue-settings-row"><span><b>{{ t('settings.creativityLabel') }}</b><small>{{ t('settings.creativityDescription', { value: ai.temperature.toFixed(1) }) }}</small></span><input type="range" min="0" max="1" step="0.1" :value="ai.temperature" @input="updateAi('temperature', Number(($event.target as HTMLInputElement).value))" /></div><label class="gm-vue-settings-row"><span><b>{{ t('settings.streamLabel') }}</b><small>{{ t('settings.streamDescription') }}</small></span><input type="checkbox" :checked="ai.streamEnabled" @change="updateAi('streamEnabled', ($event.target as HTMLInputElement).checked)" /></label><label class="gm-vue-settings-row"><span><b>{{ t('settings.webSearchLabel') }}</b><small>{{ t('settings.webSearchDescription') }}</small></span><input type="checkbox" :checked="ai.webSearchEnabled" @change="updateAi('webSearchEnabled', ($event.target as HTMLInputElement).checked)" /></label><label class="gm-vue-settings-row"><span><b>{{ t('settings.preferencePromptLabel') }}</b><small>{{ t('settings.preferencePromptDescription') }}</small></span><textarea :value="ai.customPreferencePrompt" @input="updateAi('customPreferencePrompt', ($event.target as HTMLTextAreaElement).value)" /></label><div class="gm-vue-settings-row"><span><b>{{ t('settings.searchEngineLabel') }}</b><small>{{ t('settings.searchEngineDescription') }}</small></span><select :value="webSearch.provider" @change="updateSearch('provider', ($event.target as HTMLSelectElement).value as SearchProvider)"><option value="duckduckgo">DuckDuckGo</option><option value="tavily">Tavily</option><option value="serper">Serper</option><option value="brave">Brave</option><option value="custom">{{ t('settings.customProvider') }}</option></select></div><label v-if="webSearch.provider === 'custom'" class="gm-vue-settings-row"><span><b>{{ t('settings.searchUrlLabel') }}</b><small>{{ t('settings.searchUrlDescription') }}</small></span><input :value="webSearch.customUrl" @input="updateSearch('customUrl', ($event.target as HTMLInputElement).value)" /></label><label v-if="webSearch.provider !== 'duckduckgo'" class="gm-vue-settings-row"><span><b>{{ t('settings.searchApiKeyLabel') }}</b><small>{{ t('settings.embeddingKeyDescription') }}</small></span><div class="gm-vue-settings-input-action"><input :type="showSearchKey ? 'text' : 'password'" :value="webSearch.apiKey" @input="updateSearch('apiKey', ($event.target as HTMLInputElement).value)" /><button type="button" @click="showSearchKey = !showSearchKey"><EyeOff v-if="showSearchKey" :size="14" /><Eye v-else :size="14" /></button></div></label><div class="gm-vue-settings-actions"><button type="button" :disabled="webTesting" @click="testWeb">{{ webTesting ? t('settings.connecting') : t('settings.testConnection') }}</button></div><p v-if="webResult" :class="webResult.ok ? 'gm-vue-settings-success' : 'gm-vue-settings-error'">{{ webResult.ok ? t('settings.connectionSuccess') : webResult.message || t('settings.connectionFailed') }}</p><h3>{{ t('settings.kbSection') }}</h3><label class="gm-vue-settings-row"><span><b>{{ t('settings.autoIndexLabel') }}</b><small>{{ t('settings.autoIndexDescription') }}</small></span><input type="checkbox" :checked="knowledge.autoIndexEnabled" :disabled="!isTauri()" @change="useSettingsStore.getState().updateKnowledgeSettings({ autoIndexEnabled: ($event.target as HTMLInputElement).checked })" /></label><div class="gm-vue-settings-actions"><button type="button" :disabled="!isTauri()" @click="knowledgeManagerOpen = true">{{ t('settings.manageDocuments') }}</button></div></section>
    <section v-else-if="active === 'editor'" class="gm-vue-settings-pane"><h3>{{ t('settings.appearanceSection') }}</h3><div class="gm-vue-settings-row"><span><b>{{ t('settings.fontSizeLabel') }}</b><small>{{ editor.fontSize }}px</small></span><input type="range" min="10" max="24" step="1" :value="editor.fontSize" @input="updateEditor('fontSize', Number(($event.target as HTMLInputElement).value))" /></div><div class="gm-vue-settings-row"><span><b>{{ t('settings.lineHeightLabel') }}</b><small>{{ editor.lineHeight.toFixed(2) }}</small></span><input type="range" min="1.2" max="2" step=".05" :value="editor.lineHeight" @input="updateEditor('lineHeight', Number(($event.target as HTMLInputElement).value))" /></div><div class="gm-vue-settings-row"><span><b>{{ t('settings.tabSizeLabel') }}</b><small>{{ t('settings.tabSizeDescription') }}</small></span><select :value="editor.tabSize" @change="updateEditor('tabSize', Number(($event.target as HTMLSelectElement).value))"><option :value="2">{{ t('settings.spaces2') }}</option><option :value="4">{{ t('settings.spaces4') }}</option></select></div><h3>{{ t('settings.behaviorSection') }}</h3><div class="gm-vue-settings-row"><span><b>{{ t('settings.defaultOpenModeLabel') }}</b><small>{{ t('settings.defaultOpenModeDescription') }}</small></span><div class="gm-vue-settings-segment"><button type="button" :data-active="editor.defaultOpenMode === 'edit'" @click="updateEditor('defaultOpenMode', 'edit')">{{ t('settings.edit') }}</button><button type="button" :data-active="editor.defaultOpenMode === 'preview'" @click="updateEditor('defaultOpenMode', 'preview')">{{ t('settings.preview') }}</button></div></div><label v-for="item in [{ key: 'wordWrap', label: t('settings.wordWrapLabel'), description: t('settings.wordWrapDescription') }, { key: 'lineNumbers', label: t('settings.lineNumbersLabel'), description: t('settings.lineNumbersDescription') }, { key: 'syncScroll', label: t('settings.syncScrollLabel'), description: t('settings.syncScrollDescription') }, { key: 'inlinePreviewEdit', label: t('settings.inlinePreviewEditLabel'), description: t('settings.inlinePreviewEditDescription') }, { key: 'autoSendAiShortcut', label: t('settings.autoSendAiShortcutLabel'), description: t('settings.autoSendAiShortcutDescription') }, { key: 'autoSave', label: t('settings.autoSaveLabel'), description: isTauri() ? t('settings.autoSaveDescription') : t('settings.browserUnavailable') }]" :key="item.key" class="gm-vue-settings-row"><span><b>{{ item.label }}</b><small>{{ item.description }}</small></span><input type="checkbox" :checked="Boolean(editor[item.key as keyof typeof editor])" :disabled="item.key === 'autoSave' && !isTauri()" @change="updateEditor(item.key, ($event.target as HTMLInputElement).checked)" /></label><h3>{{ t('settings.performanceSection') }}</h3><div class="gm-vue-settings-row"><span><b>{{ t('settings.perfPolicyLabel') }}</b><small>{{ modeDescription }}</small></span><div class="gm-vue-settings-segment"><button v-for="item in [{ key: 'memory', label: t('settings.policyMemory') }, { key: 'balanced', label: t('settings.policyBalanced') }, { key: 'speed', label: t('settings.policySpeed') }]" :key="item.key" type="button" :data-active="editor.modePerformancePolicy === item.key" @click="updateEditor('modePerformancePolicy', item.key)">{{ item.label }}</button></div></div></section>
    <VueMemorySettings v-else-if="active === 'memory'" />
    <VueAiShortcutSettings v-else-if="active === 'ai-shortcuts'" />
